script:
// التأكد من أن root_element متاح (ERPNext يوفره تلقائياً)
if (typeof root_element !== 'undefined') {

    // استخدام root_element للبحث عن العناصر داخل هذا البلوك تحديداً
    const wrapper = root_element.querySelector('.sync-pos-wrapper');

    if (wrapper) {
        const syncButtons = wrapper.querySelectorAll('.js-sync-link');
        const mainMenu = wrapper.querySelector('.main-menu');
        const detailView = wrapper.querySelector('.detail-view');
        const viewTitle = wrapper.querySelector('.view-title');
        const backBtn = wrapper.querySelector('.back-btn');

        // تفعيل أزرار القائمة
        syncButtons.forEach(button => {
            button.onclick = function(e) {
                // منع الرابط الافتراضي إذا كنت تريد فتح الصفحة داخل نفس البلوك (Mock View)
                // إذا كنت تريد الانتقال فعلياً لصفحة أخرى، احذف السطر التالي e.preventDefault()
                e.preventDefault(); 

                const linkName = this.getAttribute('data-link-name');
                const route = this.getAttribute('href');

                // هنا يمكنك وضع منطق التوجيه الخاص بـ Frappe إذا أردت
                // frappe.set_route(route); 

                // أو استخدام العرض التجريبي الحالي:
                if (mainMenu) mainMenu.style.display = 'none';
                if (viewTitle) viewTitle.textContent = linkName;
                if (detailView) detailView.classList.add('active');
            };
        });

        // تفعيل زر العودة
        if (backBtn) {
            backBtn.onclick = function() {
                if (detailView) detailView.classList.remove('active');
                if (mainMenu) mainMenu.style.display = 'grid'; 
            };
        }
    }
}

