/* --- تعريف المتغيرات --- */
:root {
    --sync-teal-primary: #00A8A8;
    --sync-teal-dark: #008c8c;
    --sync-teal-light: #26BFBF;
    --sync-dark-blue: #1A3C65;
    --sync-cream-bg: #F8F8F5;
    --sync-text-white: #FFFFFF;
    --sync-shadow-color: rgba(0, 168, 168, 0.2);
    --sync-gray-text: #64748b;
}

/* --- الحاوية الرئيسية --- */
.sync-pos-wrapper {
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.8);
    border-radius: 32px;
    padding: 40px;
    box-shadow: 
        0 20px 50px -12px rgba(0, 0, 0, 0.1),
        0 0 1px rgba(0,0,0,0.1);
    width: 100%;
    max-width: 900px;
    margin: 0 auto;
    direction: rtl;
    font-family: 'Cairo', 'Tajawal', sans-serif;
    position: relative;
    overflow: hidden;
    animation: slideUp 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* --- الهيدر --- */
.sync-header {
    display: flex;
    align-items: center;
    margin-bottom: 40px;
    padding-bottom: 20px;
    border-bottom: 2px solid rgba(0, 0, 0, 0.03);
    position: relative;
}

.sync-logo-icon {
    width: 58px;
    height: 58px;
    margin-left: 18px;
    filter: drop-shadow(0 4px 10px rgba(0, 168, 168, 0.25));
    animation: spinIn 0.8s ease-out;
}

.sync-title h3 {
    margin: 0;
    color: var(--sync-dark-blue);
    font-weight: 800;
    font-size: 1.8rem;
    letter-spacing: -0.5px;
}
.sync-title span { color: var(--sync-teal-primary); }
.sync-title small {
    display: block;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--sync-gray-text);
    margin-top: 4px;
}

/* --- شبكة الأزرار --- */
.sync-actions-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 25px;
}

.sync-action-btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: white;
    color: var(--sync-dark-blue);
    padding: 30px 20px;
    border-radius: 24px;
    text-decoration: none !important;
    cursor: pointer;
    border: 2px solid transparent;
    outline: none;
    box-shadow: 0 10px 30px -10px rgba(0,0,0,0.08);
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
    position: relative;
    overflow: hidden;
}

/* أيقونات الأزرار */
.sync-btn-icon {
    background: #eefbfb;
    width: 70px;
    height: 70px;
    border-radius: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 15px;
    transition: all 0.3s ease;
    color: var(--sync-teal-primary);
}

.sync-btn-icon svg {
    width: 32px;
    height: 32px;
    stroke-width: 2;
    stroke: currentColor;
    fill: none;
    transition: transform 0.3s ease;
}

.sync-btn-text {
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--sync-dark-blue);
    transition: color 0.3s ease;
}

/* --- تأثيرات التفاعل (Hover) --- */
.sync-action-btn:hover {
    transform: translateY(-5px);
    box-shadow: 0 20px 40px -12px rgba(0, 168, 168, 0.2);
    border-color: rgba(0, 168, 168, 0.3);
}

.sync-action-btn:hover .sync-btn-icon {
    background: var(--sync-teal-primary);
    color: white;
    transform: scale(1.1) rotate(-3deg);
    box-shadow: 0 10px 20px -5px rgba(0, 168, 168, 0.4);
}

.sync-action-btn:active { transform: scale(0.98); }

/* --- الرسوم المتحركة --- */
@keyframes slideUp {
    from { opacity: 0; transform: translateY(30px); }
    to { opacity: 1; transform: translateY(0); }
}
@keyframes spinIn {
    from { transform: rotate(-180deg) scale(0.5); opacity: 0; }
    to { transform: rotate(0) scale(1); opacity: 1; }
}

.sync-action-btn:nth-child(1) { animation: slideUp 0.5s 0.1s backwards; }
.sync-action-btn:nth-child(2) { animation: slideUp 0.5s 0.2s backwards; }
.sync-action-btn:nth-child(3) { animation: slideUp 0.5s 0.3s backwards; }
.sync-action-btn:nth-child(4) { animation: slideUp 0.5s 0.4s backwards; }

/* --- الشاشات الفرعية --- */
.mock-view { display: none; padding: 40px 0; text-align: center; animation: slideUp 0.4s ease; }
.mock-view.active { display: block; }

.back-btn {
    margin-top: 30px;
    background: white;
    border: 2px solid #e2e8f0;
    color: var(--sync-dark-blue);
    padding: 12px 30px;
    border-radius: 12px;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    transition: 0.3s;
    display: inline-flex;
    align-items: center;
    gap: 10px;
}
.back-btn:hover { 
    background: var(--sync-teal-primary); 
    color: white;
    border-color: var(--sync-teal-primary);
}

