script:
// سكريبت لرسم خطوط معمارية ديناميكية في الخلفية لتعزيز الهوية الهندسية
document.addEventListener('DOMContentLoaded', () => {
    const canvas = document.getElementById('architectural-canvas');
    const container = document.getElementById('arm-custom-block');

    if(!canvas || !container) return; 

    const ctx = canvas.getContext('2d');
    let width, height;
    let lines = [];

    function resizeCanvas() {
        width = container.offsetWidth;
        height = container.offsetHeight;
        canvas.width = width;
        canvas.height = height;
        initLines();
    }

    function initLines() {
        lines = [];
        const numberOfLines = Math.floor(width / 60); 

        for(let i = 0; i < numberOfLines; i++) {
            lines.push({
                x: Math.random() * width,
                y: Math.random() * height,
                length: Math.random() * 150 + 50,
                angle: Math.random() > 0.5 ? 0 : (Math.random() > 0.5 ? Math.PI/2 : Math.PI/4),
                speed: Math.random() * 0.3 + 0.1,
                opacity: Math.random() * 0.1 + 0.05
            });
        }
    }

    function draw() {
        ctx.clearRect(0, 0, width, height);

        lines.forEach(line => {
            ctx.beginPath();
            ctx.moveTo(line.x, line.y);

            const endX = line.x + Math.cos(line.angle) * line.length;
            const endY = line.y + Math.sin(line.angle) * line.length;

            ctx.lineTo(endX, endY);
            ctx.strokeStyle = `rgba(0, 0, 0, ${line.opacity})`;
            ctx.lineWidth = 1;
            ctx.stroke();

            line.x += Math.cos(line.angle) * line.speed;
            line.y += Math.sin(line.angle) * line.speed;

            if (line.x > width + 100 || line.y > height + 100 || line.x < -100 || line.y < -100) {
                line.x = Math.random() * width;
                line.y = Math.random() * height;
            }
        });

        requestAnimationFrame(draw);
    }

    window.addEventListener('resize', resizeCanvas);

    // تأخير بسيط لضمان تحميل أبعاد الـ CMS بشكل صحيح
    setTimeout(() => {
        resizeCanvas();
        draw();
    }, 100);
});

style:
/* حماية التصميم بالكامل داخل الحاوية المخصصة */
#arm-custom-block {
    --arm-black: #0a0a0a;
    --arm-white: #ffffff;
    --arm-grey-bg: #f5f5f7;
    --arm-text: #2c2c2c;
    --arm-border: #e0e0e0;
    --arm-hatch: #111111;
    font-family: 'Cairo', sans-serif !important;
    direction: rtl;
    background-color: var(--arm-grey-bg);
    position: relative;
    overflow: hidden;
    padding: 2rem;
    min-height: 100vh; /* ملء الشاشة بالكامل */
    display: flex;
    align-items: center;
    justify-content: center;
}

#arm-custom-block * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* شبكة الرسم المتحركة عبر الجافاسكريبت */
#architectural-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 1;
    opacity: 0.4;
    pointer-events: none;
}

/* المحتوى الفعلي */
.arm-content-wrapper {
    position: relative;
    z-index: 2;
    width: 100%;
    max-width: 1100px; /* تكبير العرض لملء مساحة العمل */
}

/* بطاقة المعلومات (تصميم كارت فخم وعصري) */
.arm-business-card {
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    border-radius: 8px;
    box-shadow: 0 30px 60px rgba(0,0,0,0.08), 0 0 0 1px rgba(0,0,0,0.02);
    padding: 5rem; /* زيادة المساحات الداخلية */
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    transition: transform 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.arm-business-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 40px 80px rgba(0,0,0,0.12), 0 0 0 1px rgba(0,0,0,0.02);
}

/* الشعار الهندسي */
.arm-logo-container {
    width: 100%;
    max-width: 450px; /* تكبير حجم اللوجو */
    margin-bottom: 3rem;
}

.arm-logo-svg {
    width: 100%;
    height: auto;
    overflow: visible;
}

/* حركة الدخول والخروج المتسلسلة للأحرف */
.animated-letter {
    opacity: 0;
    animation-duration: 12s; /* مدة الحركة بطيئة ومريحة للعين */
    animation-iteration-count: infinite;
    animation-timing-function: ease-in-out;
}

.letter-a { animation-name: letterAnimA; }
.letter-r { animation-name: letterAnimR; }
.letter-m { animation-name: letterAnimM; }

@keyframes letterAnimA {
    0% { opacity: 0; transform: translateY(15px); }
    10% { opacity: 1; transform: translateY(0); } /* دخول الـ A */
    70% { opacity: 1; transform: translateY(0); } 
    80% { opacity: 0; transform: translateY(-15px); } /* خروج الـ A */
    100% { opacity: 0; transform: translateY(-15px); }
}

@keyframes letterAnimR {
    0% { opacity: 0; transform: translateY(15px); }
    10% { opacity: 0; transform: translateY(15px); }
    20% { opacity: 1; transform: translateY(0); } /* دخول الـ R */
    80% { opacity: 1; transform: translateY(0); }
    90% { opacity: 0; transform: translateY(-15px); } /* خروج الـ R */
    100% { opacity: 0; transform: translateY(-15px); }
}

@keyframes letterAnimM {
    0% { opacity: 0; transform: translateY(15px); }
    20% { opacity: 0; transform: translateY(15px); }
    30% { opacity: 1; transform: translateY(0); } /* دخول الـ M */
    90% { opacity: 1; transform: translateY(0); }
    100% { opacity: 0; transform: translateY(-15px); } /* خروج الـ M */
}

/* عنوان الشركة */
.arm-title-box {
    text-align: center;
    margin-bottom: 4rem;
    width: 100%;
    border-bottom: 2px solid var(--arm-border);
    padding-bottom: 3rem;
    position: relative;
}

/* لمسة إبداعية: نقطة في منتصف الخط الفاصل */
.arm-title-box::after {
    content: '';
    position: absolute;
    bottom: -6px;
    left: 50%;
    transform: translateX(-50%);
    width: 10px;
    height: 10px;
    background-color: var(--arm-black);
    border-radius: 50%;
}

.arm-title-ar {
    font-size: 3rem !important; /* تكبير الخط العربي */
    font-weight: 700 !important;
    color: var(--arm-black) !important;
    margin-bottom: 0.8rem !important;
    letter-spacing: 0px;
}

.arm-title-en {
    font-family: 'Montserrat', sans-serif !important;
    font-size: 1.25rem !important; /* تكبير الخط الإنجليزي */
    font-weight: 500 !important;
    color: #666666 !important;
    letter-spacing: 4px;
    text-transform: uppercase;
}

/* قائمة البيانات */
.arm-contact-list {
    list-style: none !important;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3.5rem 2rem; /* زيادة المسافات بين العناصر */
    width: 100%;
}

.arm-contact-item {
    display: flex;
    align-items: center;
    gap: 1.2rem;
    color: var(--arm-text) !important;
    direction: ltr;
    justify-content: flex-end;
}

.arm-contact-item.rtl-text {
    direction: rtl;
    justify-content: flex-start;
}

/* الأيقونات المبرمجة بالـ SVG مع لمسات إبداعية */
.arm-icon-circle {
    width: 50px; /* تكبير الأيقونات */
    height: 50px;
    min-width: 50px;
    background-color: transparent;
    border: 1.5px solid var(--arm-black);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--arm-black);
    transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.arm-icon-circle svg {
    width: 20px;
    height: 20px;
    transition: transform 0.3s ease;
}

.arm-contact-item:hover .arm-icon-circle {
    background-color: var(--arm-black);
    color: var(--arm-white);
    transform: scale(1.1);
    box-shadow: 0 10px 20px rgba(0,0,0,0.15);
}

.arm-contact-item:hover .arm-icon-circle svg {
    transform: scale(0.9);
}

.arm-info-text {
    font-family: 'Montserrat', sans-serif;
    font-weight: 500;
    font-size: 1.15rem; /* تكبير نصوص التواصل */
    color: var(--arm-text);
}

.rtl-text .arm-info-text {
    font-family: 'Cairo', sans-serif;
    font-weight: 600;
}

/* التجاوب مع الشاشات الصغيرة */
@media (max-width: 768px) {
    #arm-custom-block {
        padding: 1rem;
    }
    .arm-business-card {
        padding: 3rem 1.5rem;
    }
    .arm-contact-list {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
    .arm-title-ar {
        font-size: 2.2rem !important;
    }
    .arm-title-en {
        font-size: 0.9rem !important;
    }
}
